$ErrorActionPreference='Stop'
$root=$PSScriptRoot
$review=Join-Path $root 'gemini_layer_review';New-Item -ItemType Directory -Path $review -ErrorAction Stop|Out-Null
$paths=@((Join-Path $root 'qwen_capture_comparator\capture_comparator.py'),(Join-Path $root 'qwen_capture_tests\test_capture_comparator.py'),(Join-Path $root 'COMPARATOR_CONTRACT.json'),(Join-Path $root 'ROOT_CONTRACT_CLARIFICATION.json'),'E:\the_harness\records\build_vulkan_real\toolchain\llama_clean_source\ggml\include\ggml-backend.h','E:\the_harness\records\build_vulkan_real\toolchain\llama_clean_source\ggml\src\ggml-backend.cpp')
@($paths|ForEach-Object {@{path=$_;sha256=(Get-FileHash -LiteralPath $_ -Algorithm SHA256).Hash}})|ConvertTo-Json|Set-Content -LiteralPath (Join-Path $review 'source_hashes.json')
$schema=@{type='object';properties=@{verdict=@{type='string'};findings=@{type='array';items=@{type='object';properties=@{artifact=@{type='string'};line=@{type='integer'};severity=@{type='string'};exact_source=@{type='string'};reason=@{type='string'};minimal_fix=@{type='string'};discriminating_test=@{type='string'}};required=@('artifact','severity','exact_source','reason','minimal_fix','discriminating_test')}};qualification_limits=@{type='array';items=@{type='string'}}};required=@('verdict','findings','qualification_limits')}|ConvertTo-Json -Depth 14 -Compress
$sp=Join-Path $review 'schema.json';$schema|Set-Content -LiteralPath $sp
$prompt='You are the actual Gemini reviewer in user-authorized Qwen workhorse -> Gemini review -> Grok edit. User authorizes MAXIMUM10 native child agents EACH Qwen/DeepSeek parent, but actual native children0 in this read-only review. NO imports, shell, compiler, native fixtures, GPU, writes, tools outside listed readonly files, unrelated queues, memory, web, secrets. Read ONLY listed CURRENT NEW artifact paths, not old candidates. Review actual C++ callback helper+patched fixture, Python comparator and INDEPENDENT tests against strict contract/root clarifications. No force PASS or inferred tests executed. Exact findings artifact/path/line/source/minimalfix/discriminator for actual Grok editor. Callback must use public cb_eval(t,ask,user): scheduler synchronized backend before ask=false; tensor_get synchronous, no inventedbackendhandle. callback exceptions caught, stickyfailure checked AFTER decode even if rc0; false only stops splitloop so never partial COMPLETE. F32 contiguous dims/bytes bounded, reject unsupported selectednodes/missingduplicate canonical captures. Expected exactly16 tokens0..15, BOTH KVF32 flashdisabled ctx128actual256 batch32 threads4 fixed0.01atol/rtol; no widening/narrowing, exacttype excludingbool. Sharedworkload includes intendedorderedGPU names bothCPU/GPU, CPUorigin.devices=[] separate; candidate sourcehash not oldbase, actual exe/model/filebytesSHA, pins are declarative diagnostic input not executionproof. Dump confinement lexical+resolved/reparse/symlink beforewrites, no overwritten outputs, budgets128KiBmanifest/16MiBtensor/64MiBperpass/128MiBtotal. Observer is DIAGNOSTIC_INTRUSIVE changesgraph/fusion: no mathfix/model/physicalcapacity proof. Comparator must require all expectedpins, full finite arrays + exactSHA/dtype/dims/strides/orderednodes, no metadatafromlabels only. Report ALL nodes max/RMSE/exactmismatch and separate FIRST_NOISE vs FIRST_THRESHOLD_VIOLATION; no globalreference scale. Test actual comparator via CANDIDATE_PATH, no stub function/stalepath/hash; discriminate corruptbyte/hash/truncation/duplicated JSON keys/nonfinite/missingmismatch/originfalse/tol/noise/unknownschema/pathescape. A142unique whitelist cannot isolate a145otherwise-valid node cap case; do not fake that qualification. Cite pinned files/lines. If C++ unavailable, explicitly NOT_CHECKED and review only actual Python. Return only schema JSON STATIC_REJECTED or STATIC_REVIEW_PASS_UNEXECUTED; no native approval.'+"`n"+($paths-join"`n")
$prompt += ' C++scopeNOT_CHECKED_NO_COMPLETE_CANDIDATE: originalQwenMaxHTTPtimeout240.75s, retryQwenFlashHTTP200finishlength16000tokenspartialNOT_ACCEPTED. Do NOTinventCPP review; focusONLYtwo actualPythonartifactpaths contract+rootclarifications, exactsource patches forGrok. No moreCPP retries authorized.'
$prompt|Set-Content -LiteralPath (Join-Path $review 'request.txt')
$si=[Diagnostics.ProcessStartInfo]::new('C:\Users\thoma\AppData\Local\agy\bin\agy.exe');$si.WorkingDirectory=$review;$si.UseShellExecute=$false;$si.CreateNoWindow=$true;$si.RedirectStandardOutput=$true;$si.RedirectStandardError=$true
foreach($a in @('--model','gemini-3.8-flash-medium','--mode','plan','--sandbox','--new-project','--disable-slash-commands','--output-format','json','--print-timeout','210s','--json-schema',$sp,'--log-file',(Join-Path $review 'provider.log'),'--print',$prompt)){$si.ArgumentList.Add($a)}
$p=[Diagnostics.Process]::new();$p.StartInfo=$si;$clock=[Diagnostics.Stopwatch]::StartNew();$p.Start()|Out-Null
@{pid=$p.Id;model='gemini-3.8-flash-medium';provider_deadline=210;outer_deadline=240;identity='retained Process handle';clock='Stopwatch';credential_saved=$false;native_children=0}|ConvertTo-Json|Set-Content -LiteralPath (Join-Path $review 'launch.json')
$ot=$p.StandardOutput.ReadToEndAsync();$et=$p.StandardError.ReadToEndAsync();$killed=$false
while(!$p.WaitForExit(15000)){@{seconds=[math]::Round($clock.Elapsed.TotalSeconds);state='waiting'}|ConvertTo-Json -Compress|Add-Content -LiteralPath (Join-Path $review 'heartbeat.jsonl');if($clock.Elapsed.TotalSeconds-ge240){$p.Kill($true);$killed=$true;break}}
$p.WaitForExit();$stdout=$ot.GetAwaiter().GetResult();$stderr=$et.GetAwaiter().GetResult();$stdout|Set-Content -LiteralPath (Join-Path $review 'stdout.json');$stderr|Set-Content -LiteralPath (Join-Path $review 'stderr.txt');$state='NOT_ACCEPTED'
try{$r=$stdout|ConvertFrom-Json;$u=$r.usage;$answer=$r.response;if($answer-isnot[string]){$answer=$answer|ConvertTo-Json -Depth 25};$parsed=$answer|ConvertFrom-Json;if(!$killed-and$p.ExitCode-eq0-and$null-ne$parsed.findings){$parsed|ConvertTo-Json -Depth 25|Set-Content -LiteralPath (Join-Path $review 'review.json');$state='COMPLETE_REVIEW_PENDING_ADJUDICATION'}}catch{}
@{requested_model='gemini-3.8-flash-medium';status=$state;pid=$p.Id;exit_code=$p.ExitCode;elapsed_seconds=[math]::Round($clock.Elapsed.TotalSeconds,2);outer_killed=$killed;usage=$u;native_children=0}|ConvertTo-Json -Depth 12|Set-Content -LiteralPath (Join-Path $review 'terminal.json')
